{
  "findings": [
    {
      "title": "Inconsistent sample size: 100 vs 20 per tumor type with 13 tumor types",
      "page": 90,
      "quote": "A sample size of 100 patients has been determined... Approximately 100 patients will be treated in this study, with a maximum of approximately 20 patients per tumor type... includes breast, colorectal, urothelial, esophagogastric, hepatobiliary, small cell lung, endometrial, melanoma, ovarian, cervical, salivary gland, pancreatic and cutaneous squamous-cell carcinoma.",
      "severity": "major"
    },
    {
      "title": "Contradictory statements on measurable disease at baseline",
      "page": 91,
      "quote": "All patients will have Investigator-assessed measurable disease at baseline according to inclusion criteria.",
      "severity": "major"
    },
    {
      "title": "Inconsistent PK sampling schedule: Cycle 2 and Cycle 4 vs every cycle",
      "page": 85,
      "quote": "PK sampling on Cycle 2 and Cycle 4 will be pre-dose... and post-infusion...",
      "severity": "minor"
    },
    {
      "title": "Inconsistent ADA sampling schedule: Cycle 1, 2, 4 vs every 4 cycles",
      "page": 86,
      "quote": "Blood Samples will be taken within 8 hours before administration on Day 1 of Cycles 1 Cycle 2 and Cycle 4, and then every 4 cycles and EOT and Follow up.",
      "severity": "minor"
    },
    {
      "title": "Cross-reference to non-existent Section 8.2.9",
      "page": 86,
      "quote": "Additional details are given in Section 8.2.9.",
      "severity": "minor"
    },
    {
      "title": "Cross-reference to non-existent Appendix C",
      "page": 85,
      "quote": "For further details on Handling of Human Biological Samples see Appendix C.",
      "severity": "minor"
    },
    {
      "title": "Cross-reference to non-existent Appendix I",
      "page": 85,
      "quote": "For patients diagnosed with COVID-19, please see Appendix I for further instructions on potential additional PK sample collections.",
      "severity": "minor"
    },
    {
      "title": "Cross-reference to non-existent Section 9.5",
      "page": 90,
      "quote": "See Section 9.5 for further details.",
      "severity": "minor"
    },
    {
      "title": "Inconsistent definition of FAS: 'received at least 1 dose' vs 'randomized'",
      "page": 91,
      "quote": "Full Analysis Set (FAS) All patients who received at least 1 dose of study treatment.",
      "severity": "minor"
    },
    {
      "title": "Inconsistent definition of MDAS: 'All patients will have measurable disease' vs 'who have measurable disease'",
      "page": 91,
      "quote": "Measurable Disease Analysis Set (MDAS) All patients who received at least 1 dose of study treatment, and who have Investigator-assessed measurable disease at baseline according to RECIST v1.1.",
      "severity": "minor"
    },
    {
      "title": "Inconsistent definition of CEAS: 'HER2-mutant' vs 'HER2 mutation'",
      "page": 91,
      "quote": "Centrally-determined Efficacy Analysis (CEAS) All patients who received at least 1 dose of study treatment, and who were determined as HER2- mutant via retrospective central testing according to pre-specified entry criteria.",
      "severity": "minor"
    },
    {
      "title": "Inconsistent definition of SAF: 'received at least 1 dose' vs 'randomized'",
      "page": 91,
      "quote": "Safety Analysis Set (SAF) All patients who received at least 1 dose of study treatment.",
      "severity": "minor"
    }
  ]
}
